using System;using System.IO;using System.Linq;using System.Web.Script.Serialization;using SketchRust.Compat;
class NativeFileChecks {
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 static int Main(string[] args){try{
  Directory.CreateDirectory(args[1]);
  foreach(var path in Directory.GetFiles(args[0],"blank-v*.ax7")){
   var file=ApexFile.Read(File.ReadAllBytes(path));var bytes=file.Write();var reread=ApexFile.Read(bytes);Check(reread.Version==file.Version&&reread.Pages.Count==0,"blank codec roundtrip");File.WriteAllBytes(Path.Combine(args[1],Path.GetFileName(path)),bytes);
  }
  foreach(var path in Directory.GetFiles(args[0],"reference-rectangle-v*.ax7")){
   var file=ApexFile.Read(File.ReadAllBytes(path));var refModel=file.ToModel();var area=ApexFile.Items(ApexFile.Items(refModel,"pages").First(),"polygons").First();Check(ApexFile.Str(area,"name")=="Reference first floor","reference geometry import");area["name"]="Edited from reference";area["type"]="GAR";var updated=ApexFile.FromModel(refModel,file);var data=updated.Write();File.WriteAllBytes(Path.Combine(args[1],"edited-"+Path.GetFileName(path)),data);if(file.Version>=13)Check(ApexFile.Read(data).Pages[0].Areas[0].Description=="Preserve description","native property retention");
  }
  var json=new JavaScriptSerializer{MaxJsonLength=64*1024*1024};var model=json.Deserialize<System.Collections.Generic.Dictionary<string,object>>(@"{""nextId"":20,""pages"":[{""lines"":[{""id"":1,""start"":{""x"":0,""y"":0},""end"":{""x"":20,""y"":0}},{""id"":2,""start"":{""x"":20,""y"":0},""end"":{""x"":20,""y"":10}},{""id"":3,""start"":{""x"":20,""y"":10},""end"":{""x"":0,""y"":10}},{""id"":4,""start"":{""x"":0,""y"":10},""end"":{""x"":0,""y"":0}}],""polygons"":[{""id"":5,""name"":""Original name"",""type"":""GLA1"",""points"":[{""x"":0,""y"":0},{""x"":20,""y"":0},{""x"":20,""y"":10},{""x"":0,""y"":10}],""edges"":[{""lineId"":1},{""lineId"":2},{""lineId"":3},{""lineId"":4}],""factorOverride"":-0.5}],""labels"":[{""id"":6,""text"":""Unicode \u2713"",""x"":10,""y"":5,""fontSize"":12}],""symbols"":[]}]}");
  var made=ApexFile.FromModel(model);made.Subject["FileNumber"]="NATIVE-ROUNDTRIP";var output=made.Write();File.WriteAllBytes(Path.Combine(args[1],"rectangle.ax7"),output);
  var opened=ApexFile.Read(output);Check(opened.Pages.Count==1&&opened.Pages[0].Areas.Count==1,"native populated page");Check(opened.Pages[0].Areas[0].Name=="Original name"&&opened.Pages[0].Areas[0].Sign==0,"native area semantics");
  var restored=opened.ToModel();var polygon=ApexFile.Items(ApexFile.Items(restored,"pages").First(),"polygons").First();Check(ApexFile.Str(polygon,"name")=="Original name"&&ApexFile.Num(polygon,"factorOverride")==-0.5,"model roundtrip");polygon["name"]="Edited native name";polygon["type"]="GAR";var changed=ApexFile.FromModel(restored,opened).Write();var edit=ApexFile.Read(changed);Check(edit.Pages[0].Areas[0].Name=="Edited native name"&&edit.Pages[0].Areas[0].Code=="GAR","native edit");Check(edit.Subject["FileNumber"]=="NATIVE-ROUNDTRIP","subject preserved");File.WriteAllBytes(Path.Combine(args[1],"edited.ax7"),changed);
  for(int version=1;version<=38;version++){
   var legacy=json.Deserialize<System.Collections.Generic.Dictionary<string,object>>(json.Serialize(restored));foreach(var page in ApexFile.Items(legacy,"pages"))foreach(var label in ApexFile.Items(page,"labels"))label["text"]="Legacy label";
   var file=ApexFile.FromModel(legacy,ApexFile.New(version));var bytes=file.Write();var loaded=ApexFile.Read(bytes);Check(loaded.Pages.Count==1&&loaded.Pages[0].Areas.Count==1,"version "+version+" page/area");Check(loaded.Pages[0].Areas[0].Code=="GAR","version "+version+" area code");File.WriteAllBytes(Path.Combine(args[1],"native-version-"+version+".ax7"),bytes);
  }
  var geoPage=ApexFile.Items(restored,"pages").First();geoPage["geoReferencePoints"]=new[]{ApexFile.Obj("x",3.5,"y",7.25,"coordinates","41.0 -87.0"),ApexFile.Obj("x",19,"y",-2,"coordinates","41.01 -87.02")};geoPage["geoReferenceCoordinateSystem"]="GEOGCS[\"WGS 84\"]";
  var geo=ApexFile.FromModel(restored).Write();var geoModel=ApexFile.Read(geo).ToModel();var geoRestored=ApexFile.Items(geoModel,"pages").First();Check(ApexFile.Items(geoRestored,"geoReferencePoints").Count()==2&&ApexFile.Num(ApexFile.Items(geoRestored,"geoReferencePoints").First(),"y")==7.25,"georeference native axes and data");File.WriteAllBytes(Path.Combine(args[1],"georeferences.ax7"),geo);
  if(args.Length>2){
   Advanced(model,made,args[1]);
   var library=json.Deserialize<System.Collections.Generic.Dictionary<string,object>>(File.ReadAllText(args[2]));var definitions=ApexFile.Map(ApexFile.Get(library,"symbols"));var placements=definitions.Select((entry,index)=>ApexFile.Obj("id",10000+index,"type",entry.Key,"x",index%20*20,"y",index/20*20,"scale",1,"rotation",0)).ToArray();
   var page=ApexFile.Items(restored,"pages").First();page["symbols"]=placements;restored["apexSymbols"]=definitions;restored["nextId"]=20000;
   var symbols=ApexFile.FromModel(restored).Write();File.WriteAllBytes(Path.Combine(args[1],"all-library-symbols.ax7"),symbols);var decoded=ApexFile.Read(symbols);Check(decoded.Pages[0].Blocks.Count==definitions.Count,"all symbol definitions written");var reopened=decoded.ToModel();Check(ApexFile.Items(ApexFile.Items(reopened,"pages").First(),"symbols").Count()==definitions.Count,"all symbols reopen");
   Console.WriteLine("PASS: "+definitions.Count+" native symbol blocks exported and reopened.");
  }
  Console.WriteLine("PASS: genuine native layouts v1 through v38, encrypted payloads, Unicode, geometry, names, codes, sign/factor, subject and editing roundtrip.");return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 static void Advanced(System.Collections.Generic.Dictionary<string,object> model,ApexFile made,string output){
  var json=new JavaScriptSerializer{MaxJsonLength=64*1024*1024};
  var metric=ApexFile.Read(made.Write());metric.BodyPrefix[4]=2;metric.Pages[0].Areas[0].Factor=1;metric.Pages[0].Areas[0].Sign=1;
  var feet=metric.ToModel();var feetPoly=ApexFile.Items(ApexFile.Items(feet,"pages").First(),"polygons").First();Check(Math.Abs(ApexFile.Num(ApexFile.Items(feetPoly,"points").Skip(1).First(),"x")-20/0.3048)<1e-7,"metric world conversion");var metricBytes=ApexFile.FromModel(feet,metric).Write();var restoredMetric=ApexFile.Read(metricBytes);Check(restoredMetric.Measurement==2&&Math.Abs(restoredMetric.Pages[0].Entities[0].Children[1].Values[0]-20)<1e-7,"metric native unit and coordinates preserved");File.WriteAllBytes(Path.Combine(output,"metric.ax7"),metricBytes);
  var native=ApexFile.Read(made.Write());var page=native.Pages[0];var prefix=page.Entities[0].Prefix;var inner=new ApexFile.Block{Name="inner",X=2,Y=3,Tail=new byte[21]};inner.Entities.Add(new ApexFile.Ent{Type=3,Prefix=prefix,Key=100,Values=new[]{2.0,3.0,4.0}});inner.Entities.Add(new ApexFile.Ent{Type=1,Prefix=prefix,Key=101,Values=new[]{3.0,4.0,0.0,0.0},Extras=new byte[4]});var outer=new ApexFile.Block{Name="outer",Tail=new byte[21]};outer.Entities.Add(new ApexFile.Ent{Type=23,Prefix=prefix,Key=102,Name="inner",Values=new[]{5.0,6.0,2.0,0.5,0.3}});page.Blocks.Add(inner);page.Blocks.Add(outer);page.Entities.Add(new ApexFile.Ent{Type=23,Prefix=prefix,Key=103,Name="outer",Values=new[]{30.0,40.0,-1.5,0.75,0.6}});
  outer.Entities[0].Values[2]=0;var zeroModel=native.ToModel();var zeroDef=ApexFile.Map(ApexFile.Map(ApexFile.Get(ApexFile.Map(ApexFile.Get(zeroModel,"settings")),"customSymbols")).Values.First());var zeroBounds=ApexFile.Map(ApexFile.Get(zeroDef,"bounds"));Check(ApexFile.Num(zeroBounds,"maxX")-ApexFile.Num(zeroBounds,"minX")>100,"zero native insert scale means one, as in Apex");outer.Entities[0].Values[2]=2;
  var cad=native.ToModel();var definitions=ApexFile.Map(ApexFile.Get(ApexFile.Map(ApexFile.Get(cad,"settings")),"customSymbols"));Check(definitions.Values.Any(d=>ApexFile.Items(ApexFile.Map(d),"geometry").Any(g=>ApexFile.Str(g,"entityType")=="ELLIPSE")),"nested affine ellipse conversion");var placement=ApexFile.Items(ApexFile.Items(cad,"pages").First(),"symbols").Single();placement["x"]=55.0;var cadOutput=ApexFile.FromModel(cad,native).Write();var cadRead=ApexFile.Read(cadOutput);Check(cadRead.Pages[0].Blocks.SelectMany(b=>b.Entities).Any(e=>e.Type==1),"native point survives editable symbol roundtrip");var cadAgain=cadRead.ToModel();var againDefinitions=ApexFile.Map(ApexFile.Get(ApexFile.Map(ApexFile.Get(cadAgain,"settings")),"customSymbols"));Check(ApexFile.Str(ApexFile.Map(ApexFile.Get(ApexFile.Map(againDefinitions.Values.First()),"nativeApex")),"blocks")==ApexFile.Str(ApexFile.Map(ApexFile.Get(ApexFile.Map(definitions.Values.First()),"nativeApex")),"blocks"),"original nested topology retained in native file");File.WriteAllBytes(Path.Combine(output,"nested-affine-point.ax7"),cadOutput);
  var draft=json.Deserialize<System.Collections.Generic.Dictionary<string,object>>(json.Serialize(model));var draftPage=ApexFile.Items(draft,"pages").First();var original=ApexFile.Items(draftPage,"polygons").First();draftPage["polygons"]=new object[0];draftPage["labels"]=new object[0];draftPage["lines"]=ApexFile.Items(draftPage,"lines").Where(l=>ApexFile.Num(l,"id")!=4).ToArray();draftPage["reopenedAreas"]=new[]{ApexFile.Obj("original",original,"firstReplacementId",20)};
  for(int version=1;version<=38;version++){var draftFile=ApexFile.FromModel(draft,ApexFile.New(version));var bytes=draftFile.Write();var reload=ApexFile.Read(bytes);Check(reload.Pages[0].Areas.Single().Closed==0,"real unfinished area version "+version);var decoded=ApexFile.Items(reload.ToModel(),"pages").First();Check(!ApexFile.Items(decoded,"polygons").Any()&&ApexFile.Items(decoded,"lines").Count()==3,"unfinished boundary remains open version "+version);Check(ApexFile.Items(decoded,"reopenedAreas").Count()==1,"draft count version "+version+" = "+ApexFile.Items(decoded,"reopenedAreas").Count()+" original "+json.Serialize(ApexFile.Get(decoded,"reopenedAreas")));Check(ApexFile.Str(ApexFile.Map(ApexFile.Get(ApexFile.Items(decoded,"reopenedAreas").Single(),"original")),"name")==ApexFile.Str(original,"name"),"draft area properties retained version "+version);File.WriteAllBytes(Path.Combine(output,"unfinished-v"+version+".ax7"),bytes);}
  var face=json.Deserialize<System.Collections.Generic.Dictionary<string,object>>(json.Serialize(model));face["settings"]=ApexFile.Obj("options",ApexFile.Obj("wallSolids",true,"exteriorThickness",24));var facePage=ApexFile.Items(face,"pages").First();var facePoly=ApexFile.Items(facePage,"polygons").First();facePoly["factorOverride"]=1.0;facePoly["measureTo"]="interior";facePoly["apexFactor"]=1.0;facePoly["apexNet"]=144.0;facePoly["apexBoundary"]=ApexFile.Obj("points",new[]{ApexFile.Obj("x",1,"y",1),ApexFile.Obj("x",19,"y",1),ApexFile.Obj("x",19,"y",9),ApexFile.Obj("x",1,"y",9)},"edges",ApexFile.Get(facePoly,"edges"));
  var faceBytes=ApexFile.FromModel(face).Write();var faceFile=ApexFile.Read(faceBytes);Check(faceFile.Pages[0].Entities[0].Children[0].Values[0]==1,"native measured face boundary written");var editable=ApexFile.Items(faceFile.ToModel(),"pages").First();Check(ApexFile.Num(ApexFile.Items(ApexFile.Items(editable,"polygons").First(),"points").First(),"x")==0&&ApexFile.Items(editable,"lines").Count()==4,"editable wall centers restored without duplicate outlines");File.WriteAllBytes(Path.Combine(output,"face-measured.ax7"),faceBytes);
  var graph=json.Deserialize<System.Collections.Generic.Dictionary<string,object>>(json.Serialize(model));var graphPage=ApexFile.Items(graph,"pages").First();var template=ApexFile.Items(graphPage,"polygons").First();var graphPolys=new System.Collections.Generic.List<System.Collections.Generic.Dictionary<string,object>>();foreach(var values in new[]{new[]{50.0,20.0,0.5,0.0,107.5},new[]{51.0,5.0,0.25,50.0,-7.5},new[]{52.0,1.0,2.0,51.0,20.0}}){var poly=json.Deserialize<System.Collections.Generic.Dictionary<string,object>>(json.Serialize(template));poly["id"]=values[0];poly["points"]=new[]{ApexFile.Obj("x",0,"y",0),ApexFile.Obj("x",values[1],"y",0),ApexFile.Obj("x",values[1],"y",10),ApexFile.Obj("x",0,"y",10)};poly["edges"]=new object[0];poly["factorOverride"]=values[2];poly["apexFactor"]=values[2];poly["apexNet"]=values[4];poly["apexSubtractedFromId"]=values[3]==0?null:(object)values[3];poly["subtractMode"]=values[3]==0?"never":"always";poly["subtractTargetId"]=values[3]==0?null:(object)values[3];poly["attributes"]=ApexFile.Obj("apex.calculation","net");graphPolys.Add(poly);}graphPage["polygons"]=graphPolys;graphPage["lines"]=new object[0];graphPage["labels"]=new object[0];graph["nextId"]=100;var graphBytes=ApexFile.FromModel(graph).Write();var graphModel=ApexFile.Read(graphBytes).ToModel();Check(ApexFile.Items(ApexFile.Items(graphModel,"pages").First(),"polygons").Count()==3,"factored nested graph retained");File.WriteAllBytes(Path.Combine(output,"factored-nested.ax7"),graphBytes);
  Console.WriteLine("PASS: metric conversion; nested/reflected/anisotropic CAD and native points; unfinished drafts in layouts 1–38; measured-face geometry with editable centerlines.");
 }
}
